@cached_property
def _uses_scopes(self) -> bool:
    if self.security_scopes is not None:
        return True
    for sub_dependant in self.dependencies:
        if sub_dependant._uses_scopes:
            return True
    return False

@cached_property
def cache_key(self) -> DependencyCacheKey:
    scopes = (
        tuple(sorted(set(self.security_scopes or [])))
        if self._uses_scopes
        else ()
    )
    return (
        self.call,
        scopes,
        self.computed_scope or "",
    )

